SELECT T1.OFFER_DEPT_NAME, COUNT(DISTINCT T1.SUBJECT_KEY) AS num_unique_subjects, SUM(T1.NUM_ENROLLED_STUDENTS) AS total_enrolled_students FROM SUBJECT_OFFERED AS T1 INNER JOIN TIP_SUBJECT_OFFERED AS T2 ON T1.TERM_CODE = T2.TERM_CODE WHERE T1.OFFER_DEPT_NAME = 'Harvard Cross-Enrollment Prog' AND T1.OFFER_DEPT_NAME != 'Chemistry' GROUP BY T1.OFFER_DEPT_NAME ORDER BY COUNT(DISTINCT T1.SUBJECT_KEY) DESC LIMIT 10